import React from 'react';

const QuanLyBaoTri = () => {
    const requests = [
        { id: 1, phong: 'A101', noiDung: 'Hỏng vòi nước', ngay: '16/04', status: 'Chờ xử lý' },
        { id: 2, phong: 'B202', noiDung: 'Cháy bóng đèn hành lang', ngay: '15/04', status: 'Hoàn thành' },
    ];

    return (
        <div style={{backgroundColor: '#fff', padding: '20px', borderRadius: '12px'}}>
            <h2>🔧 Yêu cầu bảo trì</h2>
            {requests.map(req => (
                <div key={req.id} style={{display: 'flex', justifyContent: 'space-between', padding: '15px', borderBottom: '1px solid #eee'}}>
                    <div>
                        <strong>Phòng {req.phong}</strong>: {req.noiDung}
                        <div style={{fontSize: '12px', color: '#888'}}>Ngày gửi: {req.ngay}</div>
                    </div>
                    <select value={req.status} style={{padding: '5px', borderRadius: '5px'}}>
                        <option>Chờ xử lý</option>
                        <option>Đang xử lý</option>
                        <option>Hoàn thành</option>
                    </select>
                </div>
            ))}
        </div>
    );
};

export default QuanLyBaoTri;
